def bfs(start, grid, R, C):
    queue = deque([start])
    visited = set()
    visited.add(start)
    distances = {}
    distances[start] = 0

    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < R and 0 <= ny < C and (nx, ny) not in visited:
                visited.add((nx, ny))
                distances[(nx, ny)] = distances[(x, y)] + 1
                queue.append((nx, ny))

    return distances

